Maintain a min-heap of the k largest values seen, counting duplicates. Its root is the kth largest value.

```javascript
function solve(nums, k) {
  const heap = [];

  for (const value of nums) {
    if (heap.length < k) {
      heap.push(value);
      let i = heap.length - 1;
      while (i > 0) {
        const parent = Math.floor((i - 1) / 2);
        if (heap[parent] <= heap[i]) break;
        [heap[parent], heap[i]] = [heap[i], heap[parent]];
        i = parent;
      }
    } else if (value > heap[0]) {
      heap[0] = value;
      let i = 0;
      while (true) {
        const left = 2 * i + 1;
        if (left >= heap.length) break;
        const right = left + 1;
        let smallest = left;
        if (right < heap.length && heap[right] < heap[left]) {
          smallest = right;
        }
        if (heap[i] <= heap[smallest]) break;
        [heap[i], heap[smallest]] = [heap[smallest], heap[i]];
        i = smallest;
      }
    }
  }

  return heap[0];
}
```

Call solve(nums, k) with valid k, as guaranteed. Time: O(n log(k + 1)); auxiliary space: O(k).

