Sort a copy numerically, then use two pointers for each distinct first value. Skipping duplicates produces unique ascending triplets, already in numeric lexicographic order.

```javascript
function solve(nums) {
  const a = nums.slice().sort((x, y) => x - y);
  const result = [];

  for (let i = 0; i < a.length - 2; i++) {
    if (i > 0 && a[i] === a[i - 1]) continue;
    if (a[i] > 0) break;

    let left = i + 1;
    let right = a.length - 1;

    while (left < right) {
      const sum = a[i] + a[left] + a[right];

      if (sum < 0) {
        left++;
      } else if (sum > 0) {
        right--;
      } else {
        result.push([a[i], a[left], a[right]]);
        const leftValue = a[left];
        const rightValue = a[right];
        left++;
        right--;
        while (left < right && a[left] === leftValue) left++;
        while (left < right && a[right] === rightValue) right--;
      }
    }
  }

  return result;
}
```

Call solve(nums) directly; no imports, exports, or stdin/stdout. Time: O(n²). Auxiliary space: O(n), plus O(t) for t returned triplets. The input is unchanged; fewer than three elements returns [].

